==triage_list==
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "status": {
      "description": "Kanban status. `draft` = AI-generated, awaiting review; `open` = on the board (default); `in_progress` = work started; `resolved` = fix shipped; `archived` = dismissed.",
      "type": "string",
      "enum": [
        "open",
        "in_progress",
        "resolved",
        "archived",
        "draft"
      ]
    },
    "severity": {
      "description": "Severity level (critical = page now, low = nice-to-have)",
      "type": "string",
      "enum": [
        "critical",
        "high",
        "medium",
        "low"
      ]
    },
    "category": {
      "description": "Fix-area category on the fix: which layer needs changing (prompt, tool, model, config, cost). Matches the `category` field returned on each fix.",
      "type": "string",
      "enum": [
        "prompt",
        "tool",
        "model",
        "config",
        "cost"
      ]
    },
    "triage_label": {
      "description": "Detailed failure taxonomy label (AgentRx). Matches the `triage_label` field on each fix \u2014 e.g. guardrail_bypass, prompt_regression.",
      "type": "string",
      "enum": [
        "prompt_regression",
        "hallucination",
        "tool_contract_misuse",
        "retrieval_miss",
        "latency_anomaly",
        "cost_anomaly",
        "orchestration_inefficiency",
        "guardrail_bypass",
        "user_frustration_signal",
        "silent_degradation"
      ]
    }
  }
}
