==triage_update_status==
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "triage_id": {
      "type": "string",
      "description": "The fix ID whose status should change"
    },
    "user_email": {
      "type": "string",
      "description": "The user's team email address. Ask the user before calling."
    },
    "status": {
      "type": "string",
      "enum": [
        "in_progress",
        "resolved",
        "archived"
      ],
      "description": "Target status. `in_progress` = work started; `resolved` = fix shipped (opens verification watch); `archived` = no longer relevant."
    },
    "resolution_note": {
      "description": "Required for `resolved` / `archived`: short note explaining the fix or why the card is being closed.",
      "type": "string"
    }
  },
  "required": [
    "triage_id",
    "user_email",
    "status"
  ]
}
==triage_update==
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "triage_id": {
      "type": "string",
      "description": "The fix ID to update"
    },
    "user_email": {
      "type": "string",
      "description": "The user's team email address. Ask the user before calling."
    },
    "title": {
      "description": "New card title",
      "type": "string"
    },
    "severity": {
      "description": "New severity",
      "type": "string",
      "enum": [
        "critical",
        "high",
        "medium",
        "low"
      ]
    },
    "triage_label": {
      "description": "New failure pattern label (e.g. `prompt_regression`, `hallucination`, `tool_contract_misuse`, `cost_anomaly`).",
      "type": "string"
    },
    "resolution_note": {
      "description": "Free-form note (audit trail)",
      "type": "string"
    },
    "root_cause": {
      "description": "Root cause analysis (markdown). Rendered as its own section on the card; editing it appends a version.",
      "type": "string"
    },
    "evidence_reasoning": {
      "description": "Evidence & reasoning (markdown). Rendered as its own section on the card; editing it appends a version.",
      "type": "string"
    },
    "recommended_action_md": {
      "description": "Recommended-action body (markdown). This is the action section only \u2014 NOT root cause or evidence (those have their own fields). Editing it appends a version.",
      "type": "string"
    }
  },
  "required": [
    "triage_id",
    "user_email"
  ]
}
